-- Provides the route-authoring coordinate converter and Lua export window.
-- Conversion works on detached route data and shares area geometry with runtime navigation.

local Constants = APR.NavigationConstants.WorldCoordinateConverter

local HereBeDragons = LibStub("HereBeDragons-2.0")
local L = LibStub("AceLocale-3.0"):GetLocale("APR")

APR.worldCoordinateConverter = APR:NewModule("WorldCoordinateConverter")

local TEXT = {
    title = L["UI_CONVERTER_TITLE"],
    route = L["UI_CONVERTER_ROUTE"],
    convert = CONVERT,
    output = L["UI_CONVERTER_OUTPUT"],
    selectRoute = L["UI_CONVERTER_SELECT_ROUTE"],
    noRoute = L["UI_CONVERTER_NO_ROUTE"],
    status = L["UI_CONVERTER_STATUS"],
